/** ساخت صفحه از مشخصه — قالب واحد کارت‌های آماری، جدول و اقدام‌ها. */
function pageFromSpec(key) {
  const s = SPEC_SCREENS[key];
  if (!s) {
    return `${pageHead('صفحهٔ ناشناخته', `کلید «${esc(String(key))}» در نمونهٔ رابط ساخته نشده است`)}
      <div class="card card-pad" style="line-height:2">
        این صفحه در مانیفست ماژول‌ها هست ولی صفحهٔ نمایشی‌اش هنوز نوشته نشده است.
        واژهٔ «ناشناخته» عمدی است: صفحهٔ گم‌شده باید دیده شود، نه اینکه به داشبورد برگردد.
      </div>`;
  }
  const actions = (s.actions || []).map((a, i) => i === 0
    ? `<button class="btn btn-primary" onclick="toast('${a} — نمونهٔ رابط')">➕ ${a}</button>`
    : `<button class="btn btn-ghost" onclick="toast('${a} — نمونهٔ رابط','info')">${a}</button>`).join(' ');
  const stats = (s.stats || []).map(([ico, tint, accent, val, label]) => statCard({ico, tint, accent, val, label})).join('');
  const rows = (s.rows || []).map(r =>
    `<tr>${r.map(c => `<td>${c}</td>`).join('')}<td>${specRowActions()}</td></tr>`);
  return `
  ${pageHead(s.title, s.sub, actions)}
  ${stats ? `<div class="grid-stats">${stats}</div>` : ''}
  ${s.note ? `<div class="card card-pad" style="margin-bottom:12px;font-size:.82rem;line-height:2">ℹ️ ${s.note}</div>` : ''}
  ${tbl(s.head, rows, {count: rows.length})}`;
}

/* ---------------------------------------------------------------------
   پروفایل پارامتریک شرکت — نمایش زندهٔ همان چیزی که پرچم `-org` در سرور عوض می‌کند
   --------------------------------------------------------------------- */
function pageOrgProfile() {
  if (!activeOrg) {
    return `${pageHead('پروفایل شرکت', 'اطلاعات شرکت‌ها بارگذاری نشده است')}
      <div class="card card-pad">پروفایل شرکت‌ها از فایل تولیدشدهٔ <span class="ltr">js/organizations.generated.js</span> خوانده می‌شود.</div>`;
  }
  const org = activeOrg;
  const allModules = [];
  for (const dir of DIRECTORATES)
    for (const dept of dir.departments || [])
      for (const g of dept.groups || [])
        for (const m of g.modules || []) if (!allModules.some(x => x.id === m.id)) allModules.push({...m, deptFa: dept.titleFa});
  const groups = {};
  for (const p of org.params) (groups[p.groupFa] = groups[p.groupFa] || []).push(p);
  const paramTables = Object.entries(groups).map(([g, list]) => `
    <div class="card" style="margin-bottom:12px">
      <div class="card-pad" style="padding-bottom:0"><b>${g}</b></div>
      <div class="tbl-wrap"><table class="tbl">
        <thead><tr><th>پارامتر</th><th>مقدار در این شرکت</th><th>واحد</th></tr></thead>
        <tbody>${list.map(p => `<tr><td>${p.titleFa}<div class="muted ltr" style="font-size:.68rem">${p.key}</div></td>
          <td><span class="chip c-ok num">${p.value}</span></td><td>${p.unitFa}</td></tr>`).join('')}</tbody>
      </table></div>
    </div>`).join('');

  const moduleRows = allModules.map(m => `<tr>
      <td>${esc(m.titleFa)}</td><td>${esc(m.deptFa)}</td>
      <td>${moduleEnabled(m.id) ? pChip('c-ok','فعال در این شرکت') : pChip('c-prob','غیرفعال')}</td>
    </tr>`);
  const orgRows = ORG_DATA.organizations.map(o => `<tr>
      <td>${o.logoEmoji} <b>${o.titleFa}</b>${o.id === org.id ? ' ' + pChip('c-ok','شرکت فعال') : ''}</td>
      <td>${o.holdingFa}</td><td class="num">${o.shortCode}</td>
      <td class="num">${fa(o.enabledDepartments.length)}</td><td class="num">${fa(o.enabledModules.length)}</td>
      <td class="num">${fa(o.headcount)}</td>
      <td><button class="btn btn-sm ${o.id === org.id ? 'btn-ghost' : 'btn-primary'}"
        onclick="switchOrg('${o.id}')">${o.id === org.id ? 'فعال' : 'شبیه‌سازی این شرکت'}</button></td>
    </tr>`);

  return `
  ${pageHead('پروفایل شرکت و پارامترهای سازمانی',
    'یک سامانه برای چند شرکت: فعال بودن ادارات و ماژول‌ها، پارامترهای حقوقی-مالی و مشخصات برند',
    `<button class="btn btn-ghost" onclick="toast('خروجی پروفایل شبیه‌سازی شد','info')">⬇️ خروجی پروفایل</button>`)}
  <div class="grid-stats">
    ${statCard({ico: org.logoEmoji, tint:'#EFF6FF', accent:'#2563EB', val: esc(org.shortCode), label: org.titleFa})}
    ${statCard({ico:'🏛️', tint:'#EDE9FE', accent:'#7C3AED', val: esc(org.holdingFa), label:'هلدینگ مالک'})}
    ${statCard({ico:'🧩', tint:'#DCFCE7', accent:'#16A34A', val: fa(org.enabledModules.length), label:`ماژول فعال از ${fa(allModules.length)}`})}
    ${statCard({ico:'👥', tint:'#FEF3C7', accent:'#D97706', val: money(org.headcount), label:'تعداد کارکنان شرکت'})}
  </div>
  <div class="card card-pad" style="margin-bottom:12px;font-size:.82rem;line-height:2">
    📌 ${org.notesFa}<br>
    <span class="muted">تقویم: ${org.calendar === 'jalali' ? 'شمسی' : 'میلادی'} · سال مالی: ${org.fiscalYearStartFa} ·
    هفتهٔ کاری: ${org.workWeekFa} · منطقهٔ زمانی: <span class="ltr">${org.timezone}</span> ·
    پیشوند کد پرسنلی: <span class="ltr">${org.employeeCodePrefix}</span></span>
  </div>
  <div class="card card-pad" style="margin-bottom:12px">
    <b>شبیه‌سازی برای شرکت‌های دیگر</b>
    <div class="muted" style="font-size:.78rem;line-height:2;margin-top:6px">
      انتخاب هر شرکت، منو، دسترسی‌ها و پارامترهای حقوقی-مالی را همان‌جا عوض می‌کند؛
      همان کاری که در استقرار واقعی پرچم <span class="ltr">-org</span> در سرور می‌کند.
      ماژول‌های غیرفعال شرکت از منو حذف می‌شوند و صفحه‌شان با مسیر دستی هم باز نمی‌شود.
    </div>
  </div>
  ${tbl(['شرکت','هلدینگ','کد','ادارهٔ فعال','ماژول فعال','کارکنان','عملیات'], orgRows, {count: orgRows.length})}
  ${paramTables}
  ${tbl(['ماژول','اداره','وضعیت در این شرکت'], moduleRows, {count: moduleRows.length})}`;
}
